API Gateway / Ingestion Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("api_gateway_ingestion_service", "API Gateway / Ingestion Service") {
    Component(Edge_Router_Validator, "Edge Router & Validator", "Go, OpenAPI", "Performs strict, declarative schema validation on incoming payment authorization requests and handles edge routing.")
    Component(Ingestion_Handler, "Ingestion Handler", "Go, gRPC / Protobuf", "Processes authorized requests and forwards scoring payloads to the Scoring Engine with sub-50ms P99 latency.")
}

Rel(Edge_Router_Validator, Ingestion_Handler, "Forwards validated authorization requests", "Internal")

@enduml

Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(scoring_engine, "Scoring Engine") {
    Component(ML_Runtime_Evaluator, "ML Runtime Evaluator", "Rust or Go, Embedded ML Runtimes, Memory-Mapped Files", "Evaluates fraud risk via embedded machine learning models using zero-downtime model weight hot-reloading.")
    Component(Telemetry_Circuit_Breaker_Manager, "Telemetry & Circuit Breaker Manager", "Prometheus", "Powers real-time telemetry, latency histograms, and circuit breaker health metrics.")
}

Rel(ML_Runtime_Evaluator, Telemetry_Circuit_Breaker_Manager, "Reports health and latency metrics", "Prometheus")

@enduml

Amazon S3 with Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon S3 with Object Lock container

System_Ext(Scoring_Engine, "Scoring Engine", "Core service for low-latency payment fraud screening")

Container_Boundary(Amazon_S3_with_Object_Lock, "Amazon S3 with Object Lock") {
    Component(Audit_Log_Storage_Component, "Audit Log Storage Component", "AWS S3 Object Lock (WORM Compliance Mode)", "Provides tamper-evident, 7-year retention storage for cryptographically chained audit logs.")
}

Rel(Scoring_Engine, Audit_Log_Storage_Component, "Asynchronously flushes and batches cryptographically chained audit logs", "AWS SDK")

@enduml

